(6037389, 887586, 52336, '<td valign="top">Lovely.  One of the better ones.  Your light is beautiful, your crop pleasing, and you''re nice to look at. :-P  (Can''t be said for every photo in the challenge.)  I might have cleaned up around the sclera and removed the rim of the contact lens that''s visible just to give it that sense of perfection, but no matter.  Very nice. 8</td>', 'Lovely.  One of the better ones.  Your light is beautiful, your crop pleasing, and you''re nice to look at. :-P  (Can''t be said for every photo in the challenge.)  I might have cleaned up around the sclera and removed the rim of the contact lens that''s visible just to give it that sense of perfection, but no matter.  Very nice. 8', '2010-06-02 11:13:16.000000', NULL, 1),
(6037390, 887542, 113419, '<td valign="top">cool set up! but for a self portrait challenge I''d wanna see more of the "self"</td>', 'cool set up! but for a self portrait challenge I''d wanna see more of the "self"', '2010-06-02 11:13:23.000000', NULL, 1),
(6037391, 886189, 52336, '<td valign="top">Yeah, definitely one of the best in the challenge.  There''s actually something substantive about you in this portrait, so we know something about who you are.  The light is sweet.  The crop, highlighting your eyes, is perfect, and the guitar is a great addition even beyond telling us what you do.  My only criticism would be the space on the left -- it''s either too much or not enough.  My preference would have been to see much more dark negative space there, which in my opinion would have created even more interest.  Excellent nonetheless, I hope it does well. 9</td>', 'Yeah, definitely one of the best in the challenge.  There''s actually something substantive about you in this portrait, so we know something about who you are.  The light is sweet.  The crop, highlighting your eyes, is perfect, and the guitar is a great addition even beyond telling us what you do.  My only criticism would be the space on the left -- it''s either too much or not enough.  My preference would have been to see much more dark negative space there, which in my opinion would have created even more interest.  Excellent nonetheless, I hope it does well. 9', '2010-06-02 11:13:34.000000', NULL, 1),
(6037392, 886374, 52336, '<td valign="top">Nice and restrained, a tad blown on the upper left, but sweet nonetheless. 7</td>', 'Nice and restrained, a tad blown on the upper left, but sweet nonetheless. 7', '2010-06-02 11:13:51.000000', NULL, 1),
(6037394, 886906, 52336, '<td valign="top">Nicely executed.  Light''s great, the portrait itself subtle and well presented.  Thank you so much for not going jokey, like everyone else.  For that reason, in this challenge even such a restrained portrait as this can be called "dignified". 8</td>', 'Nicely executed.  Light''s great, the portrait itself subtle and well presented.  Thank you so much for not going jokey, like everyone else.  For that reason, in this challenge even such a restrained portrait as this can be called "dignified". 8', '2010-06-02 11:13:57.000000', NULL, 1),
(6037396, 886327, 52336, '<td valign="top">Cool.  The props/makeup is restrained, and the portrait itself well executed. 8</td>', 'Cool.  The props/makeup is restrained, and the portrait itself well executed. 8', '2010-06-02 11:14:01.000000', NULL, 1),
(6037397, 886947, 52336, '<td valign="top">Beware of high key -- it''s hard to do.  I don''t think it''s successful here.  You''ve left a very obvious shadow below your chin, and the execution (probably enhanced in post) has left an oversharpened feel.  The colour choice isn''t good in my view, and would have worked better in black and white.  The crop is a tad severe. 5</td>', 'Beware of high key -- it''s hard to do.  I don''t think it''s successful here.  You''ve left a very obvious shadow below your chin, and the execution (probably enhanced in post) has left an oversharpened feel.  The colour choice isn''t good in my view, and would have worked better in black and white.  The crop is a tad severe. 5', '2010-06-02 11:14:13.000000', NULL, 1),
(6037401, 886935, 52336, '<td valign="top">Wow, that''s close.  Maybe too close.  I like the shallow focus, but seems to want more contrast. 6</td>', 'Wow, that''s close.  Maybe too close.  I like the shallow focus, but seems to want more contrast. 6', '2010-06-02 11:16:25.000000', NULL, 1),
(6037407, 887530, 52336, '<td valign="top">That''s cool.  I prefer the "environmental" portraits, or the ones that tell us a bit about who the individual is, or what he or she does.  This is nice.  The light''s done well and evokes an atmosphere suitable for the activity, the focus is perfect for the scene.  You''re a lefty, so an added point. :-P  8</td>', 'That''s cool.  I prefer the "environmental" portraits, or the ones that tell us a bit about who the individual is, or what he or she does.  This is nice.  The light''s done well and evokes an atmosphere suitable for the activity, the focus is perfect for the scene.  You''re a lefty, so an added point. :-P  8', '2010-06-02 11:18:16.000000', NULL, 1),
(6037412, 886465, 52336, '<td valign="top">Still, well executed, especially for a hand-held self portrait. 6</td>', 'Still, well executed, especially for a hand-held self portrait. 6', '2010-06-02 11:21:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6037414, 887238, 52336, '<td valign="top">Not crazy about the "oops, I''m just a girl" vibe I''m getting from this, intentional or not.  Oh well, I''m a curmudgeon.  5</td>', 'Not crazy about the "oops, I''m just a girl" vibe I''m getting from this, intentional or not.  Oh well, I''m a curmudgeon.  5', '2010-06-02 11:22:14.000000', NULL, 1),
(6037416, 886929, 52336, '<td valign="top">I -- yikes.  Just, yikes. 5</td>', 'I -- yikes.  Just, yikes. 5', '2010-06-02 11:24:21.000000', NULL, 1),
(6037424, 886929, 42256, '<td valign="top">HAHA ...this just made me laugh .. great take with the change of subject! You did nail the background lighting - 7</td>', 'HAHA ...this just made me laugh .. great take with the change of subject! You did nail the background lighting - 7', '2010-06-02 11:29:27.000000', NULL, 1),
