(6039007, 887730, 114225, '<td valign="top">Very well lit, and perfect sharpness.</td>', 'Very well lit, and perfect sharpness.', '2010-06-03 09:08:16.000000', NULL, 1),
(6039008, 886929, 114225, '<td valign="top">Ha, fun shot. The use of B7W works here quite well, and your pose/facial expression is priceless.</td>', 'Ha, fun shot. The use of B7W works here quite well, and your pose/facial expression is priceless.', '2010-06-03 09:09:00.000000', NULL, 1),
(6039010, 887679, 114225, '<td valign="top">Great job capturing intensity. Before reading the title, I though for sure it would be football or rugby releated.</td>', 'Great job capturing intensity. Before reading the title, I though for sure it would be football or rugby releated.', '2010-06-03 09:09:47.000000', NULL, 1),
(6039011, 887558, 114225, '<td valign="top">Fun idea for the challenge. I''m not sure I like the facial expression, unless you just cut yourself, but then I would expect to see a tiny amount of blood.</td>', 'Fun idea for the challenge. I''m not sure I like the facial expression, unless you just cut yourself, but then I would expect to see a tiny amount of blood.', '2010-06-03 09:10:47.000000', NULL, 1),
(6039012, 887396, 114225, '<td valign="top">Very basic but artsy. Interesting choice for color tone, gives a very soft feel to the photo.</td>', 'Very basic but artsy. Interesting choice for color tone, gives a very soft feel to the photo.', '2010-06-03 09:11:21.000000', NULL, 1),
(6039013, 886447, 114225, '<td valign="top">Great job with the even lighting. The white in the background is kind of stealing my attention a bit.</td>', 'Great job with the even lighting. The white in the background is kind of stealing my attention a bit.', '2010-06-03 09:12:13.000000', NULL, 1),
(6039015, 887732, 114225, '<td valign="top">Creative shot. I like the black and white, but it does feel a bit ghostly (I''m sure that''s what you were going for), which is a feeling I have never really liked much. Overall, still a nice shot.</td>', 'Creative shot. I like the black and white, but it does feel a bit ghostly (I''m sure that''s what you were going for), which is a feeling I have never really liked much. Overall, still a nice shot.', '2010-06-03 09:13:33.000000', NULL, 1),
(6039016, 886738, 114225, '<td valign="top">Good setup and fun title. I''m not a huge fan of the high key-ness to the photo, but it''s still nice.</td>', 'Good setup and fun title. I''m not a huge fan of the high key-ness to the photo, but it''s still nice.', '2010-06-03 09:14:41.000000', NULL, 1),
(6039017, 887549, 114225, '<td valign="top">Cute idea. Nice job with lighting and viewpoint.</td>', 'Cute idea. Nice job with lighting and viewpoint.', '2010-06-03 09:15:29.000000', NULL, 1),
(6039027, 886431, 114225, '<td valign="top">I like the idea here, but I don''t like the up close and personal-ness. Maybe this style shot would have looked a bit nicer (to me) in B&amp;W.</td>', 'I like the idea here, but I don''t like the up close and personal-ness. Maybe this style shot would have looked a bit nicer (to me) in B&W.', '2010-06-03 09:39:11.000000', NULL, 1),
(6039029, 886480, 114225, '<td valign="top">Basic, but it works. Good time of day for lighting, and good details.</td>', 'Basic, but it works. Good time of day for lighting, and good details.', '2010-06-03 09:40:26.000000', NULL, 1),
(6039031, 887196, 114225, '<td valign="top">An interesting idea. I''m not sure what to think of it. Well done artistically, but at the same time kind of creepy.<br/><br/><i>Message edited by author 2010-06-09 23:14:13.</i></td>', 'An interesting idea. I''m not sure what to think of it. Well done artistically, but at the same time kind of creepy.', '2010-06-03 09:42:15.000000', '2010-06-10 00:14:13.000000', 1),
