(6041320, 887264, 29009, '<td valign="top">There is something overwhelmingly sad, yet softly wonderful about this image.  Leaving it in color was an excellently subtle choice.  Very gripping work.</td>', 'There is something overwhelmingly sad, yet softly wonderful about this image.  Leaving it in color was an excellently subtle choice.  Very gripping work.', '2010-06-04 22:29:59.000000', NULL, 1),
